search_inference_docs.raw_response:
[
  {
    "criterion_id": "tool_docs_success",
    "kind": "tool_call_succeeded",
    "required": true,
    "tool_name": "find_docs"
  },
  {
    "criterion_id": "no_errors",
    "kind": "predicate",
    "required": true,
    "expression": "len(obs.get('errors', [])) == 0"
  },
  {
    "criterion_id": "docs_mention_inference",
    "kind": "predicate",
    "required": false,
    "expression": "any('inference' in str(r).lower() for r in obs['tool_results'])"
  },
  {
    "criterion_id": "valid_tool_usage",
    "kind": "predicate",
    "required": true,
    "expression": "all(r.get('tool_name') in {'find_docs', 'find_examples'} for r in obs['tool_results'])"
  },
  {
    "criterion_id": "at_least_one_tool_called",
    "kind": "predicate",
    "required": true,
    "expression": "len(obs['tool_results']) >= 1"
  }
]

